Lemma u16s_split : forall ws i w, nth_error ws i = Some w ->
  exists pre post, ws = pre ++ w :: post /\ length pre = i /\
    u16s ws = u16s pre ++ le2 w ++ u16s post /\ length (u16s pre) = (2 * i)%nat.
