Section U16.
Variable segs : list Segment.

(* [comment removed for export] *)
Lemma u16ro_read : forall m A ws (i : Z) w a,
  bytes_at segs m A (u16s ws) -> nth_error ws (Z.to_nat i) = Some w -> 0 <= i -> a = wa (A + 2 * i) ->
