Lemma u16s_of_bytes : forall (n : nat) (bs : list byte), length bs = (2 * n)%nat ->
  exists ws : list Z, length ws = n /\ Forall (fun c => - 32768 <= c < 32768) ws /\ bs = u16s (map (Z_to_bv 64) ws).
Proof.
